put('10_seed/seed-all.sql', `:on error exit
USE CinemaBookingDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @day date = TRY_CONVERT(date,N'$(SeedDate)',126);
IF @day IS NULL THROW 51004, 'SeedDate must be YYYY-MM-DD.', 1;
EXEC sys.sp_set_session_context @key=N'CinemaSeedDay',@value=@day;
DECLARE @skip int = CASE WHEN EXISTS(SELECT 1 FROM dbo.NGUOIDUNG WHERE Email='admin@cinemadb.vn') THEN 1 ELSE 0 END;
IF @skip=0 AND EXISTS(SELECT 1 FROM dbo.VAITRO) THROW 51004, 'Partial/nonempty reference data: reset before seed.', 1;
EXEC sys.sp_set_session_context @key=N'CinemaSeedSkip',@value=@skip;
BEGIN TRANSACTION;
GO
${files.map(p=>`:r ./${p}`).join('
')}
COMMIT TRANSACTION;
EXEC sys.sp_set_session_context @key=N'CinemaSeedSkip',@value=NULL;
EXEC sys.sp_set_session_context @key=N'CinemaSeedDay',@value=NULL;
PRINT 'PASS reference/demo seed (idempotent, no historical audit fixtures)';
GO`);

put('12_verify/verify_seed.sql', `IF EXISTS(SELECT MaVaiTro FROM (VALUES('ADMIN'),('QUAN_LY_RAP'),('CSKH'),('KHACH_HANG')) e(MaVaiTro) EXCEPT SELECT MaVaiTro FROM dbo.VAITRO) THROW 51005, 'Missing seed role.', 1;
IF EXISTS(SELECT MaQuyen FROM (VALUES('XEM_PHIM'),('DAT_VE'),('THANH_TOAN'),('DANH_GIA'),('GUI_KHIEU_NAI'),('QL_PHONG'),('QL_GHE')) e(MaQuyen) EXCEPT SELECT MaQuyen FROM dbo.QUYEN) THROW 51005, 'Missing seed permission.', 1;
IF EXISTS(SELECT 1 FROM dbo.QUYEN q WHERE NOT EXISTS(SELECT 1 FROM dbo.VAITRO_QUYEN vq JOIN dbo.VAITRO v ON v.VaiTroID=vq.VaiTroID WHERE v.MaVaiTro='ADMIN' AND vq.QuyenID=q.QuyenID)) THROW 51005, 'Missing admin role-permission mapping.', 1;
IF (SELECT COUNT(*) FROM dbo.NGUOIDUNG WHERE Email IN ('admin@cinemadb.vn','manager.q1@cinemadb.vn','cskh@cinemadb.vn','khachhang1@gmail.com'))<>4 THROW 51005, 'Missing demo accounts.', 1;
IF NOT EXISTS(SELECT 1 FROM dbo.PHIM) OR NOT EXISTS(SELECT 1 FROM dbo.SUATCHIEU) OR NOT EXISTS(SELECT 1 FROM dbo.GHE) OR NOT EXISTS(SELECT 1 FROM dbo.BANGGIA) OR NOT EXISTS(SELECT 1 FROM dbo.SANPHAM) OR NOT EXISTS(SELECT 1 FROM dbo.KHUYENMAI) THROW 51005, 'Missing catalog fixture.', 1;
PRINT 'PASS seed roles, permissions, mappings, accounts and catalog';
GO`);
